    public void testSample_probabilitiesSumToOne() {
        List<Pair<String, Double>> samples = new ArrayList<>();
        samples.add(new Pair<>("A", 0.3));
        samples.add(new Pair<>("B", 0.5));
        samples.add(new Pair<>("C", 0.2));

        DiscreteDistribution distribution = new DiscreteDistribution(samples);
        double sum = 0;
        for (double prob : distribution.probabilities) {
            sum += prob;
        }
        Assert.assertEquals(1.0, sum, 1e-6);
    }

