public boolean equals(Object other) {
        boolean ret;

        if (this == other) { 
            ret = true;
        } else if (other == null) {
            ret = false;
        } else  {
            try {
                Complex rhs = (Complex)other;
                if (rhs.isNaN()) {
                    ret = this.isNaN();
                } else {
                    ret = (real == rhs.real) && (imaginary == rhs.imaginary); 
                }
            } catch (ClassCastException ex) {
                // ignore exception
                ret = false;
            }
        }

        return ret;
    }

